+import fs from 'node:fs';
+import path from 'node:path';
+
+const MIGRATIONS_DIR = path.join(process.cwd(), 'supabase/migrations');
+const FUNCTION_NAME = 'public.insert_mark_decisions';
+
+function readOrderedMigrations() {
+  return fs.readdirSync(MIGRATIONS_DIR)
+    .filter((name) => name.endsWith('.sql'))
+    .sort()
+    .map((name) => ({
+      name,
+      sql: fs.readFileSync(path.join(MIGRATIONS_DIR, name), 'utf8'),
+    }));
+}
+
+function normalizeSql(sql) {
+  return sql.replace(/\s+/g, ' ').trim().toLowerCase();
+}
+
+function readMigrationHistory() {
+  return readOrderedMigrations()
+    .map(({ name, sql }) => `\n-- migration:${name}\n${sql}`)
+    .join('\n');
+}
+
+function findFunctionDefinitions(sql) {
+  const pattern = new RegExp(
+    String.raw`create\s+(?:or\s+replace\s+)?function\s+public\.insert_mark_decisions\s*\([\s\S]*?\)\s*returns\s+table\s*\([\s\S]*?\)\s*language\s+plpgsql[\s\S]*?(\$[A-Za-z_][A-Za-z0-9_]*\$|\$\$)[\s\S]*?\1\s*;`,
+    'gi',
+  );
+  return [...sql.matchAll(pattern)];
+}
+
+describe('insert_mark_decisions final effective migration contract', () => {
+  const migrationHistory = readMigrationHistory();
+  const normalizedHistory = normalizeSql(migrationHistory);
+  const definitions = findFunctionDefinitions(migrationHistory);
+
+  test('the final function definition keeps its compatible signature and fixes the definer search path', () => {
+    expect(definitions.length).toBeGreaterThan(0);
+
+    const finalDefinition = normalizeSql(definitions.at(-1)[0]);
+    expect(finalDefinition).toContain(`${FUNCTION_NAME}( p_mark_run_id uuid, p_decisions jsonb )`);
+    expect(finalDefinition).toContain('security definer set search_path = \'\'');
+    expect(finalDefinition).toContain('insert into public.mark_decisions');
+    expect(finalDefinition).toContain('from pg_catalog.jsonb_array_elements(p_decisions)');
+    expect(finalDefinition).toContain('alignment_confidence numeric');
+    expect(finalDefinition).toContain('evidence_spans jsonb');
+  });
+
+  test('the final post-definition ACL denies untrusted roles and grants only the canonical service role call', () => {
+    expect(definitions.length).toBeGreaterThan(0);
+
+    const finalDefinition = definitions.at(-1);
+    const afterFinalDefinition = normalizeSql(
+      migrationHistory.slice(finalDefinition.index + finalDefinition[0].length),
+    );
+
+    expect(afterFinalDefinition).toContain(
+      'revoke execute on function public.insert_mark_decisions(uuid, jsonb) from public, anon, authenticated',
+    );
+    expect(afterFinalDefinition).toContain(
+      'grant execute on function public.insert_mark_decisions(uuid, jsonb) to service_role',
+    );

